'use strict';
// Native desktop feature parity. Only local authenticated control routes are used.
const parity = {personas:[],active:null,editing:null,dirty:false,loaded:false,friends:[],aiDirty:false,aiHydrated:false,prefixDirty:false,loading:null,confirm:null,resourceTimer:null,consent:null,logTimer:null,resourceBusy:false,resourceLoading:null,task:null,capture:null};
function parityMsg(id,text,bad=false){const n=byId(id);if(n){n.textContent=text||'';n.classList.toggle('is-error',bad);n.setAttribute('role',bad?'alert':'status');}}
async function parityApi(path,body){const duration=path.endsWith('/wizard/capture/register')?930000:path.endsWith('/chat/restart')||path.endsWith('/ai/models')||path.endsWith('/ai/test')?120000:path.endsWith('/renew')?210000:path.endsWith('/wizard/mumu')?90000:30000;const r=await request(path,body===undefined?{timeoutMs:duration}:{method:'POST',body,timeoutMs:duration});if(r.ok===false)throw new ApiError(messageFrom(r,'操作没有完成。'),200,r);return r;}
function parityConfirm(title,text){if(parity.confirm)return Promise.resolve(false);return new Promise(resolve=>{parity.confirm=resolve;setText('parity-confirm-title',title);setText('parity-confirm-copy',text);openDialog(byId('parity-confirm-dialog'));});}
function parityConfirmDone(yes){const resolve=parity.confirm;parity.confirm=null;closeDialog(byId('parity-confirm-dialog'));if(resolve)resolve(yes);}
function parityButton(id,handler){const b=byId(id);if(b)b.addEventListener('click',async()=>{await withBusy(b,async()=>{try{await handler(b);}catch(e){showToast(friendlyError(e),'error');}});if(id.startsWith('persona-'))syncPersonaButtons();if(id.startsWith('resource-'))syncResourceButtons();});}
function syncPersonaButtons(){const p=parity.editing;byId('persona-save').disabled=!!(p&&p.preset);byId('persona-save-copy').disabled=!p;byId('persona-delete').disabled=!p||!!p.preset;byId('persona-select').disabled=!p||p.id===parity.active;}
function parityField(label,id,extra=''){return `<label class="field" for="${id}"><span>${label}</span><input id="${id}" ${extra}></label>`;}
function parityCard(title,body){return `<section class="parity-card glass-panel"><div class="panel-heading"><h2>${title}</h2></div>${body}</section>`;}
