 const footer=document.querySelector('.sidebar-foot');footer.insertAdjacentHTML('beforeend','<div class="sidebar-signature"><span class="signature-star">✦</span> 小光，陪你一起。</div>');
 const hero=document.querySelector('.hero');hero.insertAdjacentHTML('afterbegin','<div class="hero-lightfield" aria-hidden="true"><i></i><i></i><i></i></div>');
 const core=document.querySelector('.aura-core');core.innerHTML=`<svg class="companion-sculpture" viewBox="0 0 240 240" aria-hidden="true"><defs><linearGradient id="star-pearl" x1="0" y1="0" x2="1" y2="1"><stop stop-color="#fffef4"/><stop offset=".25" stop-color="#fff5c7"/><stop offset=".51" stop-color="#e4c578"/><stop offset=".72" stop-color="#a7834e"/><stop offset="1" stop-color="#efdc9e"/></linearGradient><linearGradient id="star-gloss" x1="0" y1="0" x2="1" y2="1"><stop stop-color="white" stop-opacity=".95"/><stop offset="1" stop-color="white" stop-opacity="0"/></linearGradient><filter id="star-shadow" x="-.4" y="-.3" width="1.8" height="1.8"><feDropShadow dx="7" dy="15" stdDeviation="10" flood-color="#6d7f78" flood-opacity=".22"/></filter></defs><path d="M120 29C134 77 147 89 205 114C150 137 138 154 122 211C105 156 88 140 34 122C91 101 106 84 120 29Z" fill="url(#star-pearl)" filter="url(#star-shadow)"/><path d="M120 33C118 84 120 110 123 122C101 111 79 114 40 122C94 100 107 81 120 33Z" fill="url(#star-gloss)"/><path d="M123 122C149 113 170 113 202 114C151 136 137 154 123 206Z" fill="#fff9df" opacity=".26"/><path d="M120 34C133 77 146 91 201 114" fill="none" stroke="#fffbee" stroke-width="2.5" opacity=".9"/></svg>`;
 document.querySelector('.hero-visual').insertAdjacentHTML('afterbegin','<span class="orbit-label" aria-hidden="true">ALWAYS BY YOUR SIDE</span><span class="orbit-spark spark-one" aria-hidden="true">✦</span><span class="orbit-spark spark-two" aria-hidden="true">✧</span>');
 // Anchors group long forms without hiding any existing feature.
 for(const[page,icon]of [['service','star'],['chat','chat'],['maps','map']]){const head=document.querySelector('#page-'+page+' .page-heading');head.classList.add('sculpture-heading');head.append(cloudIcon(icon,'page-sculpture'));}
 const chat=document.getElementById('page-chat'),groups=[['ai','AI 与模型',chat.querySelector('.ai-panel')],['trigger','消息触发',document.getElementById('trigger-title').closest('section')],['persona','人设',document.getElementById('persona-form').closest('section')],['owner','主人与称呼',document.getElementById('owner-select').closest('section')],['memory','聊天记忆',document.getElementById('desktop-chat-logs').closest('section')]];
 const anchors=document.createElement('nav');anchors.className='section-jumps';anchors.setAttribute('aria-label','聊天设置分区');
 for(const[key,label,section]of groups){section.id='cloud-section-'+key;const a=document.createElement('button');a.type='button';a.textContent=label;a.addEventListener('click',()=>section.scrollIntoView({block:'start',behavior:root.dataset.motion==='off'||(root.dataset.motion==='auto'&&matchMedia('(prefers-reduced-motion: reduce)').matches)?'instant':'smooth'}));anchors.append(a);}
 chat.querySelector('.page-head').after(anchors);
 // A compact current configuration fold keeps the editor in view, not removed.
 const ai=chat.querySelector('.ai-panel'),summary=document.createElement('details');summary.className='ai-current-config';summary.innerHTML='<summary>查看当前配置与可用服务商</summary>';const field=ai.querySelector('#ai-config-form');ai.querySelector('.panel-heading').after(summary);
 for(const selector of ['.detail-grid','.readout-line','#ai-base','.provider-block']){const node=ai.querySelector(selector);if(node)summary.append(node);}
