function cloudIcon(kind,className){const assets={"star":"data:image/png;base64,","chat":"data:image/png;base64,","map":"data:image/png;base64,"};const image=document.createElement("img");image.src=assets[kind];image.className=className;image.alt="";image.setAttribute("aria-hidden","true");image.draggable=false;return image;}
